import{_ as t,o,c as d,ag as a}from"./chunks/framework.HG0H2VLS.js";const g=JSON.parse('{"title":"Unassigned — Figma Notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/patterns/Unassigned/Unassigned.figma-notes.md","filePath":"public/demos/src/patterns/Unassigned/Unassigned.figma-notes.md"}'),n={name:"public/demos/src/patterns/Unassigned/Unassigned.figma-notes.md"};function s(i,e,r,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="unassigned-—-figma-notes" tabindex="-1">Unassigned — Figma Notes <a class="header-anchor" href="#unassigned-—-figma-notes" aria-label="Permalink to &quot;Unassigned — Figma Notes&quot;">​</a></h1><p><strong>Tier:</strong> Pattern <strong>Built:</strong> 2026-08-25 (Seating Planner module, wave 4b) <strong>Files:</strong> <code>Unassigned.css</code>, <code>Unassigned.html</code>, <code>Unassigned.figma.ts</code>, <code>Unassigned.figma-notes.md</code><strong>Composes:</strong> AttendeeCard (both booleans off), Input (<code>input input--sm</code>, label-less) <strong>JS:</strong> none</p><h2 id="figma-node" tabindex="-1">Figma Node <a class="header-anchor" href="#figma-node" aria-label="Permalink to &quot;Figma Node&quot;">​</a></h2><ul><li><strong>File key:</strong> <code>Lus07xi8pPXLN87sQIyrEt</code> (Affino AI — Design System)</li><li><strong>Page:</strong> Seat Planner (<code>3087:5050</code>)</li><li><strong>Component set:</strong> <code>3478:111942</code></li></ul><h2 id="variant-matrix-2-variants" tabindex="-1">Variant matrix (2 variants) <a class="header-anchor" href="#variant-matrix-2-variants" aria-label="Permalink to &quot;Variant matrix (2 variants)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Node</th><th>Figma size</th><th>CSS</th></tr></thead><tbody><tr><td>Default (empty state)</td><td><code>3478:111940</code></td><td>321×297</td><td><code>.unassigned</code> + <code>.unassigned__empty</code></td></tr><tr><td><code>Unassiged</code> [sic] (populated)</td><td><code>3478:111941</code></td><td>321×472</td><td><code>.unassigned</code> + <code>.unassigned__list</code></td></tr></tbody></table><blockquote><p><strong>Figma typo.</strong> The populated variant is named <strong><code>Unassiged</code></strong>, missing the second <code>n</code>. Worth correcting — it will read back into any Code Connect enum and into the property panel.</p></blockquote><p><strong>There is no Tier axis and no Device axis</strong> — the only property is Type. Every other component in this module carries <code>Tier=Component</code> or <code>Tier=Pattern</code>, so its absence here is an inconsistency rather than a statement. It composes two components, so CLAUDE.md §4 puts it in <code>src/patterns/</code>.</p><p><strong>Mobile safety net checked.</strong> With no Device variant, the word &quot;mobile&quot; was searched for across the design context and <code>get_variable_defs</code> output for the whole set — <strong>zero occurrences</strong>. There is genuinely no mobile layout to implement, so no media query. The panel is a fixed 320px rail at every width, as TableDetail is.</p><h3 id="the-type-axis-is-data-not-css" tabindex="-1">The Type axis is data, not CSS <a class="header-anchor" href="#the-type-axis-is-data-not-css" aria-label="Permalink to &quot;The Type axis is data, not CSS&quot;">​</a></h3><p><code>Default</code> is the empty state and <code>Unassiged</code> is the populated list. Which one renders is markup the caller supplies, so there are <strong>no Type modifiers</strong> — <code>__empty</code> and <code>__list</code> are simply different children of <code>__body</code>. Same finding as TableCard and TableDetail.</p><p>The header is byte-identical between the two variants apart from the count (<code>0</code> vs <code>6</code>).</p><h2 id="composition" tabindex="-1">Composition <a class="header-anchor" href="#composition" aria-label="Permalink to &quot;Composition&quot;">​</a></h2><p><strong>AttendeeCard with BOTH booleans off.</strong> Verified on <code>3478:111764</code>: no <code>seat</code> frame and no actions frame, just the accent bar and the name/meta block. That is exactly what AttendeeCard&#39;s <code>Show Seat Number</code> and <code>Show Actions</code> booleans are for — an unseated person has no seat to number and nothing to reorder. Nothing about AttendeeCard needed changing.</p><p><strong>Input, label-less, <code>input--sm</code>, leading search icon.</strong> <code>Input</code>&#39;s own demo already ships label-less instances, so this is precedented rather than a new usage. Given there is no visible label, the field carries <code>aria-label=&quot;Search unassigned attendees&quot;</code> — a placeholder is not an accessible name. Built as <code>&lt;input type=&quot;search&quot;&gt;</code>, which is the correct type for the control.</p><blockquote><p><strong>The PUBLISHED Code Connect for Input is stale.</strong> Figma&#39;s snippet for this instance emits <code>class=&quot;input__field&quot;</code>, but <code>input__field</code> appears <strong>zero</strong> times in <code>Input.css</code> — the class is <code>input__control</code>, and <code>Input.figma.ts</code> in the repo says <code>input__control</code> correctly. So the repo is right and Figma is serving an old publish. <strong><code>npm run code-connect:publish</code> would fix it</strong>; until then a designer copying that snippet gets markup that does not style. Left for the designer, since publishing writes to Figma.</p></blockquote><h2 id="the-search-field-spans-the-sheet" tabindex="-1">The search field spans the sheet <a class="header-anchor" href="#the-search-field-spans-the-sheet" aria-label="Permalink to &quot;The search field spans the sheet&quot;">​</a></h2><p><code>inline-size: 100%</code> on both <code>.input</code> and its <code>.input__wrap</code>, per the designer 2026-08-25.</p><p>This originally needed a <code>max-inline-size: none</code> override as well, because <code>Input</code>&#39;s <code>--sm</code> size capped the wrap at 192px so the field rendered narrower than the attendee rows beneath it. <strong>That cap was removed from Input on 2026-08-25</strong> — this was its second consumer in two days, and the third workaround overall — so the override is gone and only the width remains. See <code>Input.figma-notes.md</code> for the removal and the before/after measurements that proved it safe.</p><p>Verified: the wrap measures 286px in all three demo panels, matching the body&#39;s content box and the rows below.</p><h2 id="token-mapping" tabindex="-1">Token mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th><th>Role</th></tr></thead><tbody><tr><td><code>--ai-surface-primary</code></td><td>panel <code>background-color</code></td><td></td></tr><tr><td><code>--ai-border-secondary</code></td><td>panel + empty-state <code>border-color</code></td><td></td></tr><tr><td><code>--ai-radius-lg</code></td><td>panel <code>border-radius</code> (16px)</td><td></td></tr><tr><td><code>light/shadow-xxs</code> → <code>--ai-shadow-xxs</code></td><td>panel <code>box-shadow</code></td><td></td></tr><tr><td><code>--ai-size-6</code></td><td>panel <code>inline-size</code> (320px)</td><td>Figma draws 321 — see below</td></tr><tr><td><code>--ai-spacing-5</code></td><td>header <code>padding</code>, body <code>padding-inline</code> + <code>padding-block-end</code>, empty <code>padding-inline</code></td><td></td></tr><tr><td><code>--ai-spacing-2</code></td><td>header <code>gap</code>, empty <code>gap</code></td><td></td></tr><tr><td><code>--ai-spacing-3</code></td><td>header-row <code>gap</code>, body <code>gap</code>, list <code>gap</code></td><td></td></tr><tr><td><code>--ai-spacing-1</code></td><td>count <code>padding-block</code></td><td></td></tr><tr><td><code>--ai-spacing-4</code></td><td>count <code>padding-inline</code> (12px)</td><td></td></tr><tr><td><code>--ai-spacing-7</code></td><td>empty <code>padding-block</code> (32px)</td><td></td></tr><tr><td><code>--ai-font-title</code></td><td>every text node</td><td></td></tr><tr><td><code>--ai-font-fixed-md</code></td><td>panel title (18px)</td><td></td></tr><tr><td><code>--ai-font-fixed-4xs</code></td><td>count (11px)</td><td></td></tr><tr><td><code>--ai-font-fixed-xxs</code></td><td>hint, empty body copy (12px)</td><td></td></tr><tr><td><code>--ai-font-fixed-xs</code></td><td>empty-state heading (14px)</td><td></td></tr><tr><td><code>--ai-font-bold</code> / <code>-semibold</code> / <code>-regular</code></td><td>title / count + empty heading / hint + empty copy</td><td></td></tr><tr><td><code>--ai-leading-xs</code></td><td>hint, empty body copy (16px)</td><td>see below</td></tr><tr><td><code>--ai-leading-sm</code></td><td>empty-state heading (20px)</td><td></td></tr><tr><td><code>--ai-text-primary</code> / <code>--ai-text-contrast</code></td><td>title + empty heading / hint + count + empty copy</td><td></td></tr><tr><td><code>--ai-surface-secondary</code></td><td>count <code>background-color</code></td><td></td></tr><tr><td><code>--ai-radius-full</code></td><td>count <code>border-radius</code></td><td></td></tr><tr><td><code>--ai-radius-md</code></td><td>empty-state <code>border-radius</code> (8px)</td><td></td></tr><tr><td><code>--ai-icon-size-sm</code></td><td>empty-state tick (16px)</td><td></td></tr><tr><td><code>--ai-surface-success</code></td><td>empty-state tick colour</td><td>a SURFACE token on an icon — see below</td></tr></tbody></table><h2 id="token-gaps-and-decisions" tabindex="-1">Token gaps and decisions <a class="header-anchor" href="#token-gaps-and-decisions" aria-label="Permalink to &quot;Token gaps and decisions&quot;">​</a></h2><p>All resolved with the designer 2026-08-25 rather than invented.</p><table tabindex="0"><thead><tr><th>Figma</th><th>Decision</th></tr></thead><tbody><tr><td>panel <code>w-[321px]</code>, unbound</td><td><strong><code>--ai-size-6</code></strong> (320px). 321 has no token and is 1px off the one that exists, which TableDetail&#39;s identical rail <em>is</em> bound to. Treated as a Figma slip; worth nudging the frame to 320 and binding it.</td></tr><tr><td>empty body copy <code>line-height: 1.4</code> (unitless), unbound</td><td><strong><code>--ai-leading-xs</code></strong> (16px, i.e. 1.33). No <code>--ai-leading-*</code> token matches 1.4 — the scale is all px, and 1.4 × 12px is 16.8px. 0.8px tighter per line, ~2.4px over this three-line paragraph.</td></tr><tr><td>empty tick coloured <code>--ai-surface-success</code></td><td><strong>Used as drawn.</strong> A <em>surface</em> token doing an icon&#39;s job, because <strong>the icon scale has no success entry at all</strong> — it stops at primary / secondary / contrast / invert / invert-secondary / brand, while surfaces and text both have success/error/warning. 3.16:1 on white clears the 3:1 WCAG asks of a graphical object, so this is safe; but <strong><code>--ai-icon-success</code> is a genuine hole in the scale</strong> and worth filling.</td></tr><tr><td><code>Orange/600</code> (<code>#ea580c</code>) in the set&#39;s variable list</td><td><strong>Not a gap.</strong> Present in <code>get_variable_defs</code> but used by nothing in this component — the same phantom seen on TableDetail. Likely bound on a hidden layer or in another Seating Planner mode.</td></tr></tbody></table><h2 id="height-grows-with-content" tabindex="-1">Height: grows with content <a class="header-anchor" href="#height-grows-with-content" aria-label="Permalink to &quot;Height: grows with content&quot;">​</a></h2><p>Figma sets <strong>no height</strong> on either variant, so the panel is as tall as its contents — built that way.</p><p><strong>This differs from TableDetail deliberately</strong>, where Figma <em>did</em> pin a height (698px) and the designer replaced it with fill-the-column plus a scrolling list. Here there is nothing to replace.</p><blockquote><p><strong>Worth a decision before this goes in the module template.</strong> A tray with fifty unseated people will grow unbounded and take the page scroll with it, where TableDetail&#39;s equivalent list scrolls inside a fixed header. Nothing was invented here — Figma is unambiguous — but the two side rails will behave differently until someone says which is right.</p></blockquote><h2 id="interaction-model" tabindex="-1">Interaction model <a class="header-anchor" href="#interaction-model" aria-label="Permalink to &quot;Interaction model&quot;">​</a></h2><ul><li><strong>Presentational only, no JS.</strong> In the real module these rows are the drag <strong>sources</strong> that the seat rows (AttendeeCard&#39;s <code>--dragged-over</code>) receive. The parent owns dragging on both sides, so neither component ships it.</li><li>The search field filters the list — also the parent&#39;s job. No JS here.</li><li>The count is supplied, not computed. See the handover note.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong><code>Seating Status Badge</code> is an inline frame, not a component instance.</strong> <code>get_metadata</code> reports it as <code>&lt;frame&gt;</code> where <code>Input</code> and <code>Attendee Card</code> report as <code>&lt;instance&gt;</code>, so it is correctly scoped as <code>.unassigned__count</code>. Renders 31×22 against Figma&#39;s 32×21 — within text-metric noise.</li><li><strong>The body slot has two names</strong>: <code>Body</code> on Type=Default, <code>guest-list</code> on Type=Unassiged. The same container modelled twice — the identical inconsistency TableDetail has.</li><li><strong><code>Left-Footer-Area</code> is the frame name for the hint line.</strong> That name has now been reused for three unrelated things across the module (TableCard&#39;s count+badge group, TableDetail&#39;s meta line, this hint). Figma layer-naming noise; worth a sweep.</li><li><strong>A single-child flex wrapper around the hint</strong> was dropped — <code>Left-Footer-Area</code> has one child and a gap, which does nothing.</li><li>Rendered panel heights are <strong>296 / 480</strong> against Figma&#39;s 297 / 472. The empty state is 1px under; the populated one is 8px over, which is exactly the panel&#39;s 2px border plus 1px of <code>box-sizing: border-box</code> on each of the six cards. Cosmetic arithmetic in an auto-height panel.</li><li><strong>No hover, focus, pressed or disabled variants</strong> in the set, and no dark-mode variant. The <code>--sp-*</code> role colours on the rows are <strong>not</strong> theme-aware.</li><li>The Lucide names match Figma&#39;s layer names: <code>circle-check</code> for <code>Icon/24px/CircleCheck</code>, <code>search</code> for the Input icon.</li></ul>',33)])])}const m=t(n,[["render",s]]);export{g as __pageData,m as default};
